-- Reviewed source-to-data instance. Records are interpretations with stated basis.
CREATE TABLE research_register.study_evidence_instance (instance_id VARCHAR PRIMARY KEY, review_status VARCHAR NOT NULL, reviewed_date DATE NOT NULL, science_source_id VARCHAR NOT NULL REFERENCES research_register.science_source(source_id), assertion_id VARCHAR NOT NULL REFERENCES research_register.science_assertion(assertion_id), hypothesis_assertion_id VARCHAR NOT NULL REFERENCES research_register.science_assertion(assertion_id), reading_depth VARCHAR NOT NULL, publication_url VARCHAR NOT NULL, dataset_doi VARCHAR NOT NULL, dataset_url VARCHAR NOT NULL, worksheet_sha256 VARCHAR NOT NULL);
CREATE TABLE research_register.study_evidence_component (instance_id VARCHAR NOT NULL REFERENCES research_register.study_evidence_instance(instance_id), position INTEGER NOT NULL, component_type VARCHAR NOT NULL, description VARCHAR NOT NULL, source_locator VARCHAR NOT NULL, basis VARCHAR NOT NULL, PRIMARY KEY(instance_id,position));
CREATE TABLE research_register.study_evidence_review_flag (instance_id VARCHAR NOT NULL REFERENCES research_register.study_evidence_instance(instance_id), position INTEGER NOT NULL, flag VARCHAR NOT NULL, PRIMARY KEY(instance_id,position));
CREATE TABLE research_register.study_evidence_file (instance_id VARCHAR NOT NULL REFERENCES research_register.study_evidence_instance(instance_id), local_name VARCHAR NOT NULL, source_name VARCHAR NOT NULL, md5 VARCHAR NOT NULL, source_url VARCHAR NOT NULL, row_count INTEGER, column_count INTEGER, PRIMARY KEY(instance_id,local_name));
